func Icon(name string) string { return UIIcons[name] }

func FormatTime(value int64) string {
	if value <= 0 {
		return "—"
	}
	return time.UnixMilli(value).Format("Jan 2, 2006, 3:04 PM")
}

func navLink(href, key, label string, active bool) string {
	className := ""
	if active {
		className = ` class="active"`
	}
	return `<a href="` + href + `" aria-label="` + Escape(label) + `" title="` + Escape(label) + `"` + className + `><span class="nav-icon">` + UIIcons[key] + `</span><span>` + Escape(label) + `</span></a>`
}

func DashboardPage(options DashboardOptions) string {
	initial := "U"
	if strings.TrimSpace(options.Email) != "" {
		initial = strings.ToUpper(string([]rune(options.Email)[0]))
	}
	brand := `<div class="brand"><img class="logo" src="/assets/codelocal-icon.png" alt=""><span class="brand-name">CodeLocal</span><span class="brand-tag">MCP</span><button class="mobile-nav-toggle" type="button" aria-label="Open navigation" aria-expanded="false" data-nav-toggle><span class="control-icon">` + UIIcons["menu"] + `</span></button></div>`
	var nav strings.Builder
	nav.WriteString(`<div class="nav-label">Control plane</div><nav class="nav">`)
	nav.WriteString(navLink("/dashboard", "overview", "Overview", options.Active == "overview"))
	nav.WriteString(navLink("/dashboard/workspaces", "workspaces", "Workspaces", options.Active == "workspaces"))
	nav.WriteString(navLink("/dashboard/knowledge", "knowledge", "Knowledge Graph", options.Active == "knowledge"))
	nav.WriteString(navLink("/dashboard/code-graph", "codegraph", "Code Graph", options.Active == "codegraph"))
	nav.WriteString(navLink("/dashboard/devices", "devices", "Devices", options.Active == "devices"))
	nav.WriteString(navLink("/dashboard/connect", "connect", "MCP Connections", options.Active == "connect"))
	nav.WriteString(navLink("/dashboard/account", "account", "Account", options.Active == "account"))
	nav.WriteString(`</nav><div class="nav-label">Community</div><nav class="nav">`)
	nav.WriteString(navLink("/dashboard/invite", "invite", "Invite", options.Active == "invite"))
	nav.WriteString(navLink("/dashboard/leaderboard", "leaderboard", "Leaderboard", options.Active == "leaderboard"))
	if options.IsAdmin {
		nav.WriteString(`</nav><div class="nav-label">Administration</div><nav class="nav">`)
		nav.WriteString(navLink("/dashboard/admin", "admin", "Admin", options.Active == "admin"))
	}
	nav.WriteString(`</nav>`)
	logout := `<form method="post" action="/logout">` + Hidden(map[string]string{"csrf": options.CSRF}) + `<button class="btn ghost small" type="submit" aria-label="Sign out" title="Sign out"><span class="signout-icon" aria-hidden="true">` + UIIcons["logout"] + `</span><span class="signout-label">Sign out</span></button></form>`
	status := `<div class="sidebar-spacer"></div><div class="sidebar-status"><div class="sidebar-status-title"><span class="status-dot green"></span>Cloud connected</div><div class="sidebar-status-copy">Local source code and secrets stay on your machine.</div></div><div class="sidebar-foot"><div class="avatar">` + Escape(initial) + `</div><div class="account"><div class="account-email">` + Escape(options.Email) + `</div><div class="account-meta">CodeLocal account</div></div>` + logout + `</div>`
	subtitle := ""
	if strings.TrimSpace(options.Subtitle) != "" {
		subtitle = `<div class="sub">` + Escape(options.Subtitle) + `</div>`
	}
	actions := ""
	if strings.TrimSpace(options.Actions) != "" {
		actions = `<div class="top-actions">` + options.Actions + `</div>`
	}
	header := ""
	if options.Active != "overview" {
		header = `<header class="top"><div class="top-copy"><div class="eyebrow"><span class="status-dot green"></span>CodeLocal Cloud</div><div class="h1">` + Escape(options.Title) + `</div>` + subtitle + `</div>` + actions + `</header>`
	}
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">` + brandHead + `<title>` + Escape(options.Title) + ` · CodeLocal</title><style>` + styles + mainPortExtras + iosDashboardTheme + `</style></head><body class="dashboard-body page-` + Escape(options.Active) + `"><div class="shell"><div class="sidebar-column"><aside class="sidebar">` + brand + nav.String() + status + `</aside></div><main class="main">` + header + options.Body + `</main></div><dialog id="confirm-dialog"><div class="modal"><div class="modal-icon">` + UIIcons["warning"] + `</div><div class="modal-title" id="confirm-title">Are you sure?</div><div class="modal-copy" id="confirm-copy">This action cannot be undone.</div><div class="modal-actions"><button class="btn" type="button" onclick="this.closest('dialog').close()">Cancel</button><button class="btn danger" id="confirm-submit" type="button">Continue</button></div></div></dialog><script>` + dashboardScript + `</script></body></html>`
}
func LandingPage(options LandingOptions) string {
	endpoint := Escape(options.Endpoint)
	accountAction := `<a class="btn ghost" href="/login">Sign in</a><a class="btn primary" href="/register">Create account</a>`
	heroSecondary := `<a class="btn" href="/register">Create account</a>`
	finalPrimary := `<a class="btn primary" href="/register">Create your account <span class="landing-btn-icon" aria-hidden="true">` + UIIcons["arrowRight"] + `</span></a>`
	if options.SignedIn {
		accountAction = `<a class="btn primary" href="/dashboard">Open dashboard</a>`
		heroSecondary = `<a class="btn" href="/dashboard">Open dashboard</a>`
		finalPrimary = `<a class="btn primary" href="/dashboard">Open your dashboard <span class="landing-btn-icon" aria-hidden="true">` + UIIcons["arrowRight"] + `</span></a>`
	}
	year := fmt.Sprint(time.Now().Year())
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#05070c">` + brandHead + `<meta name="description" content="A universal MCP layer that connects MCP-compatible AI clients and coding agents to one durable Project Brain and controlled local runtime."><title>CodeLocal · Universal MCP + Project Brain for AI coding</title><style>` + styles + landingStyles + landingTechTheme + `</style></head><body class="landing-body"><div class="landing">
<nav class="landing-nav"><div class="landing-nav-inner"><a class="landing-brand" href="/"><img class="landing-logo" src="/assets/codelocal-icon.png" alt="CodeLocal"><span>CodeLocal</span></a><div class="landing-nav-center"><a href="#product">Product</a><a href="#brain">Project Brain</a><a href="#workflow">How it works</a><a href="#setup">Setup</a><a href="#security">Security</a></div><div class="landing-links">` + accountAction + `</div></div></nav>
<main class="landing-main">
<section class="landing-hero"><div class="landing-hero-copy-wrap"><div class="landing-kicker"><span class="status-dot green"></span>Private by design · universal MCP · persistent project intelligence</div><h1>Connect every AI.<span>Keep one project brain.</span></h1><div class="landing-hero-copy">Switch between ChatGPT, Claude, Codex and other MCP-compatible agents without rebuilding project context. CodeLocal keeps one Project Brain and one controlled local runtime behind them all.</div><div class="hero-value"><span class="hero-value-mark">↳</span><strong>Switch AI without rebuilding project context.</strong><span>Your rules, decisions and verified experience stay with the project.</span></div><div class="landing-actions"><a class="btn primary" href="#setup">Set up CodeLocal <span class="landing-btn-icon" aria-hidden="true">` + UIIcons["arrowRight"] + `</span></a>` + heroSecondary + `</div><div class="landing-trust"><span class="trust-chip">` + UIIcons["shield"] + `Local execution</span><span class="trust-chip">` + UIIcons["check"] + `Approval + policy</span><span class="trust-chip">` + UIIcons["folderCheck"] + `Explicit projects only</span></div></div>
<div class="architecture-panel" role="img" aria-label="AI clients connect through MCP to CodeLocal. CodeLocal resolves project context, applies policy, executes on the authorized local runtime, verifies evidence and promotes only durable experience."><div class="arch-head"><div><div class="arch-kicker">Architecture map</div><div class="arch-title">AI client → CodeLocal → your machine</div><div class="arch-sub">MCP carries the request. CodeLocal resolves context, enforces policy and executes locally.</div><div class="arch-plain-language"><span><b>01</b> Connect</span><span><b>02</b> Govern</span><span><b>03</b> Execute locally</span></div></div><span class="arch-live"><span class="status-dot green"></span>Local runtime ready</span></div><div class="arch-main"><div class="arch-zone"><div class="arch-zone-title">AI clients</div><div class="arch-client-list"><div class="arch-client"><img src="` + ChatGPTLogoDataURI + `" alt="ChatGPT"><span>ChatGPT / Codex</span></div><div class="arch-client"><img src="/assets/claude.svg" alt="Claude"><span>Claude</span></div><div class="arch-client"><img src="/assets/moonshotai.svg" alt="Kimi"><span>Kimi</span></div><div class="arch-client"><img src="/assets/deepseek.svg" alt="DeepSeek"><span>DeepSeek</span></div></div></div><div class="arch-rail"><div class="arch-protocol"><strong>MCP</strong><span>OAuth</span></div></div><div class="arch-core"><div class="arch-core-logo"><img src="/assets/codelocal-icon.png" alt="CodeLocal"></div><strong>CodeLocal</strong><span>Universal MCP control layer<br>project resolution · bounded context · routing</span><div class="arch-policy">Approval + security policy outrank automation</div></div><div class="arch-rail"><div class="arch-protocol"><strong>SECURE RPC</strong><span>authenticated</span></div></div><div class="arch-zone arch-runtime"><div class="arch-zone-title">Your machine · local runtime</div><div class="arch-cap-grid"><div class="arch-cap local">Files</div><div class="arch-cap local">Git</div><div class="arch-cap local">Terminal</div><div class="arch-cap local">Browser / Computer</div><div class="arch-cap">LSP + code index</div><div class="arch-cap">Local approvals</div></div></div></div><div class="arch-lower"><div class="arch-layer brain"><div class="arch-layer-title">Project Brain <span>durable intelligence</span></div><div class="arch-tags"><span class="arch-tag">Rules</span><span class="arch-tag">Decisions</span><span class="arch-tag">Memory</span><span class="arch-tag">Learned Skills</span><span class="arch-tag">Knowledge Graph</span><span class="arch-tag">Semantic index</span></div></div><div class="arch-layer verify"><div class="arch-layer-title">Verification <span>evidence</span></div><div class="arch-tags"><span class="arch-tag">Diagnostics</span><span class="arch-tag">Tests</span><span class="arch-tag">Git diff</span><span class="arch-tag">Quality policy</span></div></div><div class="arch-layer experience"><div class="arch-layer-title">Verified Experience <span>reuse</span></div><div class="arch-tags"><span class="arch-tag">Provenance</span><span class="arch-tag">Revisions</span><span class="arch-tag">Safe promotion</span></div></div></div><div class="arch-loop"><span>Local result</span><strong>→ verify → keep durable knowledge →</strong><span>next AI session</span></div><div class="arch-cloud"><span class="arch-cloud-badge">CodeLocal Cloud</span><div class="arch-cloud-copy"><strong>Cloud stores:</strong> identity, routing, logical project identity and sanitized durable Project Brain knowledge. <strong>Local stays local:</strong> raw source, secrets, terminal execution, device credentials and machine-specific indexes.</div></div></div></section>
<section class="architecture-flow" id="workflow"><div class="flow-heading"><div class="section-kicker">The complete flow</div><h2 class="landing-section-title">From request to verified experience — without turning your repository into a cloud upload.</h2><div class="section-copy">Every task passes through project resolution, bounded context, local policy and verification before anything becomes reusable knowledge.</div></div><div class="complete-flow-grid"><article class="flow-step"><div class="flow-step-number">01</div><strong>User request</strong><span>Ask from ChatGPT, Claude, Kimi, DeepSeek, Codex or another MCP client.</span></article><article class="flow-step"><div class="flow-step-number">02</div><strong>MCP session</strong><span>OAuth identity, tool surface and the selected CodeLocal connection are resolved.</span></article><article class="flow-step"><div class="flow-step-number">03</div><strong>Project resolve</strong><span>Repository identity, branch, workspace and applicable project rules are determined.</span></article><article class="flow-step"><div class="flow-step-number">04</div><strong>Context compile</strong><span>Only relevant rules, knowledge, skills and code ranges become the task packet.</span></article><article class="flow-step guard"><div class="flow-step-number">05</div><strong>Policy + approval</strong><span>Security policy, path scope and risky actions are checked before execution.</span></article><article class="flow-step local"><div class="flow-step-number">06</div><strong>Execute locally</strong><span>Files, Git, terminal, browser/computer and code tools run on your machine.</span></article><article class="flow-step local"><div class="flow-step-number">07</div><strong>Verify evidence</strong><span>Diagnostics, tests, diff and quality policy judge whether the result is real.</span></article><article class="flow-step learn"><div class="flow-step-number">08</div><strong>Learn + return</strong><span>Verified Experience can be promoted to Project Brain, then the response returns to the AI client.</span></article></div></section>
<section class="landing-section" id="product"><div class="section-heading-row"><div><div class="section-kicker">Built for long-lived projects</div><h2 class="landing-section-title">Your code stays local. Useful project knowledge persists.</h2></div><div class="section-copy">CodeLocal is the persistent project-intelligence and controlled-execution layer around the AI model. It exposes only authorized local workspaces while preserving verified rules, decisions, experiences and reusable workflows across conversations.</div></div><div class="product-grid"><article class="product-card wide"><div class="product-icon">` + UIIcons["folderCheck"] + `</div><div class="product-title">Authorize projects, not your whole computer.</div><div class="product-copy">Run <strong>codelocal .</strong> inside a project once. Only that workspace becomes available to connected MCP clients, and removing access never deletes your files.</div><div class="product-terminal">cd /path/to/project
codelocal .</div></article><article class="product-card narrow"><div class="product-icon">` + UIIcons["device"] + `</div><div class="product-title">One lightweight machine runtime.</div><div class="product-copy">Pair a computer once, keep CodeLocal running, and let multiple authorized workspaces sleep until a conversation needs them.</div><div class="product-badges"><span class="product-pill">macOS</span><span class="product-pill">Windows</span><span class="product-pill">Linux</span></div></article><article class="product-card half"><div class="product-icon">` + UIIcons["shield"] + `</div><div class="product-title">Sensitive actions stay gated.</div><div class="product-copy">Potentially destructive terminal and filesystem operations require approval before they execute on your machine.</div></article><article class="product-card half"><div class="product-icon">` + UIIcons["sparkles"] + `</div><div class="product-title">Use the AI client you already prefer.</div><div class="product-copy">Connect CodeLocal once through MCP, then use the same authorized projects and Project Brain from ChatGPT, Codex, Claude or another MCP-compatible AI client.</div></article></div></section>
<section class="brain-section" id="brain"><div class="section-kicker">Project Brain</div><h2 class="landing-section-title">The model can change. Your project memory does not have to.</h2><div class="section-copy">CodeLocal keeps a small, durable layer of verified project knowledge outside any single chat or model. It resolves what matters for the current task, gives the AI only a bounded context packet, verifies the work locally, then learns only from evidence worth keeping.</div><div class="brain-flow" role="img" aria-label="Request flows through Project Brain to the AI model, then to the local runtime, verification and verified experience"><div class="brain-node"><span class="brain-node-kicker">1 · Resolve</span><strong>Project Brain</strong><small>Rules · decisions · memory · skills</small></div><span class="brain-arrow">→</span><div class="brain-node"><span class="brain-node-kicker">2 · Reason</span><strong>AI model</strong><small>Receives a compact task-specific packet</small></div><span class="brain-arrow">→</span><div class="brain-node"><span class="brain-node-kicker">3 · Act</span><strong>Local runtime</strong><small>Authorized files · Git · terminal · tools</small></div><span class="brain-arrow">→</span><div class="brain-node"><span class="brain-node-kicker">4 · Prove</span><strong>Verify & learn</strong><small>Checks → Experience → safe promotion</small></div></div><div class="brain-principles"><div><strong>Not “remember everything”</strong><span>Operational noise stays activity, not durable knowledge.</span></div><div><strong>Semantic is optional</strong><span>If semantic recall becomes slow or unreliable, CodeLocal falls back to deterministic retrieval.</span></div><div><strong>Cross-device continuity</strong><span>Project identity follows repository evidence instead of one machine path.</span></div></div></section>
<section class="setup-section" id="setup"><div class="section-kicker">Setup guide</div><h2 class="landing-section-title">Setup and maintenance in six steps.</h2><div class="section-copy">The detailed flow stays here when you need it; the product surface above remains focused on what CodeLocal actually does.</div><div class="setup-layout"><div class="setup-list">
<details class="setup-step" open><summary><span class="step-number">1</span><span><span class="step-title">Connect your AI client through MCP</span><span class="step-summary">Use the public integration when available, or add the CodeLocal MCP endpoint in any compatible client.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><ol class="step-details"><li><strong>ChatGPT / Codex:</strong> install <strong>CodeLocal</strong> from the OpenAI Plugins Directory when publicly available and complete OAuth authorization.</li><li><strong>Other MCP-compatible clients:</strong> add <strong>` + endpoint + `</strong> as a remote MCP server and use OAuth when the client supports remote authenticated MCP.</li><li><strong>Reviewer/developer testing:</strong> use the same endpoint in the client's custom MCP/developer flow.</li><li>Authenticate with the CodeLocal account that owns the paired devices and workspaces.</li><li>Client capabilities, approval UX and write-action availability may vary by AI product and workspace policy.</li></ol></div></details>
<details class="setup-step"><summary><span class="step-number">2</span><span><span class="step-title">Install CodeLocal</span><span class="step-summary">Install the current stable runtime on your development machine.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">npm install -g codelocal</div><div class="step-note"><strong>If npm reports EEXIST:</strong> run <code>npm uninstall -g codelocal</code>, then install again. Avoid <code>--force</code> unless you verified the conflicting file.</div></div></details>
<details class="setup-step"><summary><span class="step-number">3</span><span><span class="step-title">Pair this computer</span><span class="step-summary">Create a private device credential for this machine.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">codelocal</div><ol class="step-details"><li>Your browser opens the approval page automatically.</li><li>Sign in with the same CodeLocal account.</li><li>Verify the machine name, approve it, then return to the terminal.</li></ol></div></details>
<details class="setup-step"><summary><span class="step-number">4</span><span><span class="step-title">Authorize a project folder</span><span class="step-summary">Grant each workspace explicitly.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">cd /path/to/project
codelocal .</div><div class="step-note">Repeat <code>codelocal .</code> only inside projects you want connected MCP clients to access.</div></div></details>
<details class="setup-step"><summary><span class="step-number">5</span><span><span class="step-title">Start working from your AI client</span><span class="step-summary">Keep the machine runtime on, then choose a workspace for the current MCP session.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><ol class="step-details"><li>Enable or connect <strong>CodeLocal</strong> in your AI client.</li><li>Ask it to list your authorized workspaces.</li><li>Select the project you need; sleeping workspaces activate only when selected.</li><li>Approve sensitive local actions when CodeLocal asks.</li></ol></div></details>
<details class="setup-step"><summary><span class="step-number">6</span><span><span class="step-title">Reset or uninstall CodeLocal</span><span class="step-summary">Return to first-time setup or remove CodeLocal completely.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">codelocal reset --all
codelocal uninstall --all</div><ol class="step-details"><li><strong>reset --all</strong> stops the runtime and removes local login, workspace grants, approvals, indexes, history, managed Chromium and capability settings, while keeping the CLI installed.</li><li><strong>uninstall --all</strong> removes the same local data and then removes the global npm package.</li><li>Both commands ask for confirmation. Add <strong>--yes</strong> only for an intentional non-interactive cleanup.</li><li>Operating-system privacy permissions such as macOS Accessibility and Screen Recording remain controlled by the OS.</li></ol></div></details>
</div><aside class="plugin-panel"><div class="plugin-panel-head"><img class="plugin-panel-icon" src="/assets/chatgpt-plugin-icon.png" alt="CodeLocal Plugin icon"><div><div class="plugin-panel-title">CodeLocal MCP</div><div class="plugin-panel-sub">One remote endpoint for compatible AI clients</div></div></div><div class="plugin-endpoint"><div class="plugin-endpoint-label">Server URL</div><div class="plugin-endpoint-value">` + endpoint + `</div></div><div class="plugin-specs"><div class="plugin-spec"><span class="plugin-spec-key">Authentication</span><span class="plugin-spec-value">OAuth</span></div><div class="plugin-spec"><span class="plugin-spec-key">Transport</span><span class="plugin-spec-value">Remote MCP</span></div><div class="plugin-spec"><span class="plugin-spec-key">OpenAI listing icon</span><span class="plugin-spec-value">256 × 256 PNG</span></div></div><button class="btn primary" type="button" data-copy-value="` + endpoint + `"><span class="landing-btn-icon" aria-hidden="true">` + UIIcons["copy"] + `</span>Copy MCP URL</button><a class="btn" href="/assets/chatgpt-plugin-icon.png" download="codelocal-chatgpt-plugin-icon.png">Download OpenAI listing icon</a><div class="size-ok"><span class="size-ok-icon">` + UIIcons["check"] + `</span>Prepared for OpenAI plugin review</div></aside></div></section>
<section class="security-section" id="security"><div class="security-hero"><div><div class="section-kicker">Private by design</div><h2 class="landing-section-title">Your machine is the execution boundary.</h2><div class="section-copy">CodeLocal Cloud coordinates identity, routing and sanitized durable Project Brain knowledge. Raw source code, project secrets, local credentials and execution context remain on the paired computer.</div></div><div class="security-mark" aria-hidden="true">` + UIIcons["shield"] + `</div></div><div class="security-points"><article class="security-card"><div class="security-icon">` + UIIcons["folderCheck"] + `</div><div class="security-title">Explicit workspace access</div><div class="security-copy">Only folders you authorize appear to connected MCP clients. Revoking access leaves project files untouched.</div></article><article class="security-card"><div class="security-icon">` + UIIcons["check"] + `</div><div class="security-title">Approval for risky actions</div><div class="security-copy">Sensitive terminal and filesystem operations stay behind your local confirmation policy.</div></article><article class="security-card"><div class="security-icon">` + UIIcons["device"] + `</div><div class="security-title">Revocable device credentials</div><div class="security-copy">Review paired machines from the dashboard and revoke any device you no longer trust.</div></article></div></section>
<section class="final-cta"><div class="cta-card"><div class="section-kicker">Start in one command</div><div class="cta-title">Give your AI tools local capability without giving up local control.</div><div class="cta-copy">Connect through one MCP layer, pair one machine, authorize only the projects you choose, and keep the rest of your computer outside the boundary.</div><div class="cta-command"><code>npm install -g codelocal</code><button class="cta-copy-button" type="button" data-copy-value="npm install -g codelocal" aria-label="Copy install command">` + UIIcons["copy"] + `<span>Copy</span></button></div><div class="cta-actions">` + finalPrimary + `<a class="btn" href="#setup">Read setup guide</a></div></div></section>
<footer class="landing-footer"><span class="landing-footer-brand"><img src="/assets/codelocal-icon.png" alt="">CodeLocal</span><span>© ` + year + ` · <a href="/privacy">Privacy</a> · <a href="/security">Security</a> · <a href="/terms">Terms</a> · <a href="/support">Support</a></span></footer>
</main></div><script>` + landingScript + `</script></body></html>`
}

func MetricCard(label string, value any, sub string) string {
	return `<div class="card metric-card span4"><div class="metric-label">` + Escape(label) + `</div><div class="metric">` + Escape(fmt.Sprint(value)) + `</div><div class="metric-sub">` + Escape(sub) + `</div></div>`
}
